package com.jnapanam.sportszone.notification.service;
import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationProviderSettingsService{private final JdbcTemplate j;private final SecretKeySpec key;public NotificationProviderSettingsService(JdbcTemplate j,@Value("${app.security.jwt-secret}")String secret){this.j=j;try{byte[] hash=MessageDigest.getInstance("SHA-256").digest(secret.getBytes(StandardCharsets.UTF_8));key=new SecretKeySpec(hash,"AES");}catch(Exception e){throw new IllegalStateException(e);}}
 public String value(String k,String fallback){List<String>x=j.query("select encrypted_value from notification_provider_settings where setting_key=?",(rs,n)->rs.getString(1),k);return x.isEmpty()?fallback:decrypt(x.get(0));}
 public Map<String,Object> masked(){Map<String,Object>m=new LinkedHashMap<>();for(String k:List.of("SMTP_HOST","SMTP_PORT","SMTP_USERNAME","SMTP_PASSWORD","SMTP_FROM","FAST2SMS_API_KEY","FAST2SMS_SENDER_ID","FAST2SMS_OTP_ID","WHATSAPP_PROVIDER_URL","WHATSAPP_PROVIDER_TOKEN")){String v=value(k,"");m.put(k,Map.of("configured",!v.isBlank(),"value",secret(k)?mask(v):v));}return m;}
 @Transactional public void save(UUID actor,Map<String,Object>b){for(var e:b.entrySet()){if(!allowed(e.getKey()))continue;String v=String.valueOf(e.getValue()==null?"":e.getValue()).trim();if(v.isEmpty()||v.contains("••••"))continue;j.update("insert into notification_provider_settings(setting_key,encrypted_value,updated_by) values(?,?,?) on conflict(setting_key) do update set encrypted_value=excluded.encrypted_value,updated_by=excluded.updated_by,updated_at=now()",e.getKey(),encrypt(v),actor);}}
 private boolean allowed(String k){return List.of("SMTP_HOST","SMTP_PORT","SMTP_USERNAME","SMTP_PASSWORD","SMTP_FROM","FAST2SMS_API_KEY","FAST2SMS_SENDER_ID","FAST2SMS_OTP_ID","WHATSAPP_PROVIDER_URL","WHATSAPP_PROVIDER_TOKEN").contains(k);}private boolean secret(String k){return k.contains("PASSWORD")||k.contains("KEY")||k.contains("TOKEN");}private String mask(String v){return v.isBlank()?"":"••••••••";}
 private String encrypt(String v){try{byte[] iv=new byte[12];SecureRandom.getInstanceStrong().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[] enc=c.doFinal(v.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(iv)+"."+Base64.getEncoder().encodeToString(enc);}catch(Exception e){throw new IllegalStateException(e);}}
 private String decrypt(String v){try{String[]p=v.split("\\.",2);byte[]iv=Base64.getDecoder().decode(p[0]);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,iv));return new String(c.doFinal(Base64.getDecoder().decode(p[1])),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Unable to decrypt provider setting",e);}}
}
